@Test
public void testLargeUpdate() {
    final UpdateableDataContext dataContext = new ElasticSearchRestDataContext(client, INDEX_NAME);
    final Schema schema = dataContext.getDefaultSchema();
    final CreateTable createTable = new CreateTable(schema, DEFAULT_TABLE_NAME);
    createTable.withColumn("id").ofType(ColumnType.NUMBER);
    createTable.withColumn("firstname").ofType(ColumnType.STRING);
    createTable.withColumn("lastname").ofType(ColumnType.STRING);
    dataContext.executeUpdate(createTable);
    final Table table = schema.getTableByName(DEFAULT_TABLE_NAME);
    assertNotNull(table);
    dataContext.executeUpdate(new UpdateScript() {

        @Override
        public void run(final UpdateCallback callback) {
            IntStream.range(1, 1000).forEach(id -> callback.insertInto(table).value("id", id).value("firstname", "first" + id).execute());
        }
    });
    try (DataSet dataSet = dataContext.query().from(table).select("id", "firstname", "lastname").execute()) {
        dataSet.forEach(row -> {
            assertNotNull(row.getValue(0));
            assertNotNull(row.getValue(1));
            assertNull(row.getValue(2));
        });
    }
    dataContext.executeUpdate(new UpdateScript() {

        @Override
        public void run(final UpdateCallback callback) {
            IntStream.range(1, 1000).forEach(id -> callback.update(table).where("id").eq(id).value("lastname", "last" + id).execute());
        }
    });
    try (DataSet dataSet = dataContext.query().from(table).select("id", "firstname", "lastname").execute()) {
        dataSet.forEach(row -> {
            assertNotNull(row.getValue(0));
            assertNotNull(row.getValue(1));
            assertNotNull(row.getValue(2));
        });
    }
}

@Test
public void testClose() throws IOException {
    final RestClient client = createMock(RestClient.class);
    final Response clearScrollResponse = createMock(Response.class);
    final HttpEntity httpEntity = createMock(HttpEntity.class);
    final Header header = createMock(Header.class);
    // Instead of mocking all the classes above, I would rather just mock the RestHighLevelClient, because I only
    // want to verify that the clearScroll method is invoked on it when the ElasticSearchRestDataSet is closed, but
    // because of the manner in which the RestHighLevelClient is implemented it's impossible to mock this in a nice
    // manner.
    final RestHighLevelClient restHighLevelClient = new MockRestHighLevelClient(client);
    final SearchResponse searchResponse = createMock(SearchResponse.class);
    final ClearScrollRequest clearScrollRequest = new ClearScrollRequest();
    clearScrollRequest.addScrollId("id");
    expect(searchResponse.getScrollId()).andReturn("id");
    expect(client.performRequest(anyObject())).andReturn(clearScrollResponse);
    expect(clearScrollResponse.getEntity()).andReturn(httpEntity);
    expect(httpEntity.getContentType()).andReturn(header).anyTimes();
    expect(header.getValue()).andReturn("application/*").anyTimes();
    expect(httpEntity.getContent()).andReturn(new ByteArrayInputStream("{\"succeeded\": true,\"num_freed\": 3}".getBytes()));
    EasyMock.replay(client, searchResponse, clearScrollResponse, httpEntity, header);
    final DataSet dataSet = new ElasticSearchRestDataSet(restHighLevelClient, searchResponse, Collections.emptyList());
    dataSet.close();
    EasyMock.verify(client, searchResponse, clearScrollResponse, httpEntity, header);
}

