    Schema schema = getDataContext().getSchemaByName("HR");
    Table employeeTable = schema.getTableByName("EMPLOYEES");
    Table departmentsTable = schema.getTableByName("DEPARTMENTS");
    Optional<Relationship> relationship = employeeTable.getRelationships(departmentsTable).stream().filter(rel -> rel.toString().equals("Relationship[primaryTable=EMPLOYEES,primaryColumns=[EMPLOYEE_ID],foreignTable=DEPARTMENTS,foreignColumns=[MANAGER_ID]]")).findFirst();
    assertTrue(relationship.isPresent());
    Query q = new Query().from(new FromItem(JoinType.INNER, relationship.get())).select(employeeTable.getColumnByName("EMAIL"), departmentsTable.getColumnByName("DEPARTMENT_NAME"));
    q.getSelectClause().getItem(0).setAlias("e-mail");
    assertEquals("SELECT \"EMPLOYEES\".\"EMAIL\" AS e-mail, \"DEPARTMENTS\".\"DEPARTMENT_NAME\" FROM HR.\"EMPLOYEES\" INNER JOIN HR.\"DEPARTMENTS\" ON \"EMPLOYEES\".\"EMPLOYEE_ID\" = \"DEPARTMENTS\".\"MANAGER_ID\"", q.toString());
    DataSet data = getDataContext().executeQuery(q);
    assertNotNull(data);
    TableModel tableModel = new DataSetTableModel(data);
    assertEquals(2, tableModel.getColumnCount());
    assertEquals(11, tableModel.getRowCount());
    boolean found = false;
    for (int i = 0; i < tableModel.getRowCount(); i++) {
        if (tableModel.getValueAt(i, 0).toString().equals("JWHALEN")) {
            assertEquals("Administration", tableModel.getValueAt(i, 1).toString());
            found = true;
            break;
        }
    }
    assertTrue(found);
}

