    JdbcDataContext dc = new JdbcDataContext(connection);
    final Schema schema = dc.getSchemaByName("Person");
    assertEquals("Person", schema.getName());
    dc.executeUpdate(new UpdateScript() {

        @Override
        public void run(UpdateCallback cb) {
            Table table = cb.createTable(schema, "test_table").withColumn("id").asPrimaryKey().ofType(ColumnType.INTEGER).withColumn("birthdate").ofType(ColumnType.DATE).execute();
