@Test
public void testRead() throws Exception {
    if (!isConfigured()) {
        System.err.println(getInvalidConfigurationMessage());
        return;
    }
    mongoDb.createCollection(getCollectionName());
    MongoCollection<Document> col = mongoDb.getCollection(getCollectionName());
    // create 1000 records
    for (int i = 0; i < 1000; i++) {
        Document dbRow = new Document();
        dbRow.put("id", i);
        dbRow.put("name", "record no. " + i);
        if (i % 5 == 0) {
            dbRow.put("foo", "bar");
        } else {
            dbRow.put("foo", "baz");
        }
        Document nestedObj = new Document();
        nestedObj.put("count", i);
        nestedObj.put("constant", "foobarbaz");
        dbRow.put("baz", nestedObj);
        dbRow.put("list", Arrays.<Object>asList("l1", "l2", "l3", i));
        col.insertOne(dbRow);
    }
    // Instantiate the actual data context
    final DataContext dataContext = new MongoDbDataContext(mongoDb);
    assertTrue(dataContext.getDefaultSchema().getTableNames().contains(getCollectionName()));
    final Table table = dataContext.getDefaultSchema().getTableByName(getCollectionName());
    assertEquals("[_id, baz, foo, id, list, name]", Arrays.toString(table.getColumnNames().toArray()));
    assertEquals(ColumnType.MAP, table.getColumnByName("baz").getType());
    assertEquals(ColumnType.STRING, table.getColumnByName("foo").getType());
    assertEquals(ColumnType.LIST, table.getColumnByName("list").getType());
    assertEquals(ColumnType.INTEGER, table.getColumnByName("id").getType());
    assertEquals(ColumnType.ROWID, table.getColumnByName("_id").getType());
    DataSet ds = dataContext.query().from(getCollectionName()).select("name").and("foo").and("baz").and("list").where("id").greaterThan(800).or("foo").isEquals("bar").execute();
    assertEquals(MongoDbDataSet.class, ds.getClass());
    assertFalse(((MongoDbDataSet) ds).isQueryPostProcessed());
    try {
        assertTrue(ds.next());
        assertEquals("Row[values=[record no. 0, bar, Document{{count=0, constant=foobarbaz}}, [l1, l2, l3, 0]]]", ds.getRow().toString());
        assertTrue(ds.next());
        assertEquals("Row[values=[record no. 5, bar, Document{{count=5, constant=foobarbaz}}, [l1, l2, l3, 5]]]", ds.getRow().toString());
        assertTrue(ds.next());
        assertEquals("Row[values=[record no. 10, bar, Document{{count=10, constant=foobarbaz}}, [l1, l2, l3, 10]]]", ds.getRow().toString());
        for (int j = 15; j < 801; j++) {
            if (j % 5 == 0) {
                assertTrue(ds.next());
                assertEquals("Row[values=[record no. " + j + ", bar, Document{{count=" + j + ", constant=foobarbaz}}, [l1, l2, l3, " + j + "]]]", ds.getRow().toString());
            }
        }
        assertTrue(ds.next());
        assertTrue(ds.getRow().getValue(2) instanceof Map);
        assertEquals(Document.class, ds.getRow().getValue(2).getClass());
        assertTrue("unexpected type: " + ds.getRow().getValue(3).getClass(), ds.getRow().getValue(3) instanceof List);
        assertEquals(ArrayList.class, ds.getRow().getValue(3).getClass());
        assertEquals("Row[values=[record no. 801, baz, Document{{count=801, constant=foobarbaz}}, [l1, l2, l3, 801]]]", ds.getRow().toString());
        assertTrue(ds.next());
        assertEquals("Row[values=[record no. 802, baz, Document{{count=802, constant=foobarbaz}}, [l1, l2, l3, 802]]]", ds.getRow().toString());
        assertTrue(ds.next());
        assertEquals("Row[values=[record no. 803, baz, Document{{count=803, constant=foobarbaz}}, [l1, l2, l3, 803]]]", ds.getRow().toString());
        assertTrue(ds.next());
        assertEquals("Row[values=[record no. 804, baz, Document{{count=804, constant=foobarbaz}}, [l1, l2, l3, 804]]]", ds.getRow().toString());
        assertTrue(ds.next());
        assertEquals("Row[values=[record no. 805, bar, Document{{count=805, constant=foobarbaz}}, [l1, l2, l3, 805]]]", ds.getRow().toString());
        for (int i = 0; i < 194; i++) {
            assertTrue(ds.next());
        }
        assertEquals("Row[values=[record no. 999, baz, Document{{count=999, constant=foobarbaz}}, [l1, l2, l3, 999]]]", ds.getRow().toString());
        assertFalse(ds.next());
    } finally {
        ds.close();
    }
    ds = dataContext.query().from(getCollectionName()).select("id").and("name").where("id").in(2, 6, 8, 9).execute();
    assertTrue(ds.next());
    assertEquals("Row[values=[2, record no. 2]]", ds.getRow().toString());
    assertTrue(ds.next());
    assertEquals("Row[values=[6, record no. 6]]", ds.getRow().toString());
    assertTrue(ds.next());
    assertEquals("Row[values=[8, record no. 8]]", ds.getRow().toString());
    assertTrue(ds.next());
    assertEquals("Row[values=[9, record no. 9]]", ds.getRow().toString());
    assertFalse(ds.next());
    ds.close();
    ds = dataContext.query().from(getCollectionName()).select("id").and("name").where("foo").isEquals("bar").execute();
    assertEquals(MongoDbDataSet.class, ds.getClass());
    assertFalse(((MongoDbDataSet) ds).isQueryPostProcessed());
    try {
        List<Object[]> objectArrays = ds.toObjectArrays();
        assertEquals(200, objectArrays.size());
        assertEquals("[0, record no. 0]", Arrays.toString(objectArrays.get(0)));
    } finally {
        ds.close();
    }
    // test GREATER_THAN_OR_EQUAL
